"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["16351"],{12529(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.itens_em_excesso","status":422,"titulo":"O formul\xe1rio excede o teto de itens"},"descricao":{"codigo":"uniplus.item_formulario.itens_em_excesso","requisitos":[],"oQueAconteceu":["Um formul\xe1rio tem no m\xe1ximo 200 itens. O teto conta cada item, cada grupo repet\xedvel e cada campo de grupo, e no formul\xe1rio de inscri\xe7\xe3o conta tamb\xe9m os itens dos dados b\xe1sicos do candidato. Acima dele, a lista \xe9 recusada inteira, sem um erro por item. A mensagem \xe9 \\"O formul\xe1rio admite no m\xe1ximo 200 itens; vieram `{n\\\\}`.\\", com a quantidade contada.","A recusa vem na lista `errors` da resposta, com `field` igual a `itens`; nos modelos de formul\xe1rio, `conteudo.itens`. Nada \xe9 gravado. A forma de cada item e de cada grupo n\xe3o \xe9 conferida item a item enquanto a quantidade estiver acima do teto.","Na grava\xe7\xe3o dos itens do formul\xe1rio, a quantidade \xe9 a primeira confer\xeancia do conte\xfado, depois do estado do processo, e conta o que o pedido envia. Quando o pedido omite `grupos`, o formul\xe1rio mant\xe9m os grupos que j\xe1 tem, e a quantidade somada a eles \xe9 conferida por \xfaltimo, depois de todas as outras recusas dos itens; nesse caso a mensagem pode trazer uma quantidade maior que a dos itens enviados. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e a confer\xeancia dos fatos contra o cat\xe1logo, que n\xe3o depende da quantidade, pode sair na mesma resposta. Na atualiza\xe7\xe3o, um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Reduza o formul\xe1rio a at\xe9 200 itens, contando os grupos e os campos de grupo. Se o conte\xfado \xe9 grande por natureza, divida-o entre formul\xe1rios de finalidades diferentes, quando o processo comportar."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);